fn visual_onehome(uv: vec2f, fieldSize: vec2f, t: f32) -> vec4f {
  let p = uv / fieldSize;
  var col = mix(vec3f(0.015, 0.018, 0.045), vec3f(0.05, 0.03, 0.09), p.y);
  // drifting star layers — the void the catalog floats in
  for (var l: i32 = 0; l < 3; l++) {
    let lf = f32(l);
    let sc = 18.0 + lf * 26.0;
    let drift = vec2f(t * (0.004 + lf * 0.006), 0.0);
    let g = (p + drift) * sc;
    let cell = floor(g);
    let h = fract(sin(dot(cell, vec2f(127.1, 311.7))) * 43758.5453);
    let star = smoothstep(0.985 - lf * 0.004, 1.0, h);
    let tw = 0.6 + 0.4 * sin(t * (1.0 + h * 3.0) + h * 40.0);
    col += vec3f(0.9, 0.85, 1.0) * star * tw * (0.25 + lf * 0.2);
  }
  // a faint amber hearth-glow low center — the cafe's ember
  let d = distance(p, vec2f(0.5, 0.85));
  col += vec3f(0.45, 0.25, 0.08) * exp(-d * d * 9.0) * 0.35;
  return vec4f(col, 1.0);
}
